"""Explicit review of 55 pending LEP units; no inferred approval of the rest."""
import copy,json,sys
from pathlib import Path
p=Path(sys.argv[1]);old=json.loads((p/'pending-existing.json').read_text())[:55];expected={r['unit']['unit_key']:r for r in old};rows={}
LEP='https://www.planalto.gov.br/ccivil_03/leis/l7210.htm'
CP='https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm'
HEALTH='https://www.planalto.gov.br/ccivil_03/leis/leis_2001/l10216.htm'
L407='https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15407.htm'
L410='https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15410.htm'
L402='https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15402.htm'
L358='https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15358.htm'
L843='https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l14843.htm'
STFEX='https://noticias.stf.jus.br/postsnoticias/stf-vai-decidir-se-exigencia-de-exame-criminologico-para-progressao-de-regime-vale-para-crimes-anteriores/'
STFEXIT='https://noticias.stf.jus.br/postsnoticias/stf-mantem-saida-temporaria-de-condenado-por-roubo-cometido-antes-do-fim-do-beneficio/'
def SUM(n):return f'https://processo.stj.jus.br/SCON/sumstj/doc.jsp?b=SUMU&i=1&l=10&p=false&sumula={n}+INPATH%28NUM%29'
def add(n,case,var,q1,q2,**patch):
 k='art-'+str(n);e=copy.deepcopy(expected[k]['explanation']);r={f:e[f] for f in ['simples','pontos','atencao','exemplo','prova','termos','remissoes']};r.update(exemplo=case+' Variação: '+var,prova=[q1,q2]);r['atencao']+=patch.pop('notes',[]);r['pontos']+=patch.pop('extra_points',[]);r['remissoes']=list(dict.fromkeys([LEP,*r['remissoes'],*patch.pop('sources',[])]));r.update(patch)
 if not r['termos']:r['termos']=[dict(termo='Regra do art. '+str(n),significado=r['simples'])]
 rows[k]=r
add(50,'Condenado por violência doméstica, em saída autorizada e sob medida protetiva pertinente, aproxima-se do trabalho da vítima. Resposta: examinar inciso IX.', 'A presença casual em qualquer bairro, sem os requisitos descritos, não prova automaticamente essa falta.', 'O inciso IX alcança qualquer condenado, sem medida protetiva? Não. Exige condenação por violência doméstica, contexto de regime/benefício e medidas do art. 22, II/III, da Maria da Penha.', 'Recusa de DNA autoriza coleta irrestrita de qualquer pessoa? Não. Integrar âmbito e garantias da identificação genética; previsão de falta não elimina requisitos legais.',notes=['Lei 15.410 assinada em 20/5/2026, publicada e vigente em 21/5/2026; inciso IX não é original de 1984.','Aplicação ao provisório apenas NO QUE COUBER, sem transformar condenação exigida no inciso IX em requisito inexistente.','Apuração, defesa e individualização das consequências: não RDD automático para toda falta.'],sources=[L410])
add(52,'Diretor requer RDD desde recolhimento, indicando pressupostos concretos. Resposta: pedido é possível pelo §10, mas não inclusão administrativa automática.', 'O §8º vetado na Lei 15.407 foi posteriormente inserido pela Lei 15.410; não memorizar só o veto antigo.', 'Todo crime doloso gera RDD automaticamente? Não. Caput exige subversão interna para esse recorte; §§1º/8º têm pressupostos próprios e a inclusão depende do regime judicial do 54.', 'Toda entrevista com defensor é gravada livremente pelo inciso V? Não. O inciso excepciona defensor; integrar 41-A/B, sigilo e garantias. Não há monitoramento universal por simples condição de preso.',simples='Crime doloso constitui falta grave; RDD no caput exige subversão da ordem/disciplina, com decisão judicial. Há hipóteses próprias de alto risco/fundadas suspeitas (§1º) e ameaça/violência contra vítima de violência doméstica/familiares (§8º). Inicial até dois anos; prorrogação anual depende dos pressupostos do §4º. Defensor é exceção do monitoramento do inciso V, integrada às normas especiais e garantias. §6º exige autorização judicial para gravação da visita. §10 permite requerimento desde recolhimento, presentes pressupostos; não inclusão automática.',atencao=['Lei 15.407: publicada 12/5/2026, retificada 22/5; §§1º,III/IV e §9º vetados não criam requisitos atuais.','Lei 15.410: §8º atual desde 21/5/2026; veto anterior não impediu inserção posterior.','Lei Antifacção 15.358/2026 alterou §6º. ADIs 7952/7956/7957/7958: audiência pública não equivale a decisão de mérito. Não certificada solução de todo controle constitucional posterior.','Telefonema do §7º: após primeiros seis meses, sem a visita, agendado, família, duas vezes/mês, dez minutos.','Não confundir duração inicial, repetição por nova falta e prorrogações anuais fundamentadas.'],sources=[L407,L410,L358],termos=[dict(termo='RDD',significado='Regime disciplinar com pressupostos próprios e controle judicial, distinto de todo regime fechado.')])
add(54,'Pedido de RDD recebe exame liminar e decisão final motivada até quinze dias. Resposta: são etapas distintas, com oportunidade de manifestação do MP e defesa.', 'Silêncio após oportunidade regular não se confunde com impedir a defesa de participar.', 'A falta de resposta permite nem intimar a defesa? Não. O §3º não elimina oportunidade de defesa; integra-se ao §2º e garantias. Ausência de manifestação e ausência de oportunidade são distintas.', 'O prazo final de quinze dias é igual ao isolamento preventivo de dez dias? Não. Art. 54 regula decisão do RDD; art. 60 tem medida preventiva própria.',simples='RDD depende de decisão judicial fundamentada e requerimento circunstanciado. Lei 15.407/2026 prevê exame liminar e decisão final até quinze dias após manifestações do MP e defesa. §3º permite decidir diante de ausência de manifestação, sem autorizar supressão da oportunidade de defesa. Caput sobre sanções administrativas deve ser integrado ao art. 41, §1º, atual, que exige ato judicial motivado para restringir os direitos ali enumerados.',atencao=['Lei 15.407 publicada/vigente em 12/5/2026, retificada 22/5. Conferência editorial em 13/10 não é data original/vigência.','Não converter silêncio em negativa de defesa ou prazo final em duração máxima de todo RDD.','Não certificada solução de todas as controvérsias constitucionais da decisão liminar/silêncio.'],sources=[L407])
add(96,'Centro realiza exame criminológico e encaminha resultado à Comissão Técnica. Resposta: exame subsidia classificação, não concede sozinho progressão.', 'Pesquisas criminológicas são possíveis, com requisitos éticos; não experimentação compulsória livre.', 'O Centro decide progressão por ter realizado exame? Não. Exames e classificação são funções distintas da decisão judicial do art. 112.', 'O parágrafo obriga pesquisa científica em todo preso? Não. Diz PODERÃO ser realizadas pesquisas, com garantias éticas e jurídicas aplicáveis.')
add(97,'Centro funciona em anexo a estabelecimento penal. Resposta: forma expressamente permitida, além da unidade autônoma.', 'Anexo não elimina requisitos de segurança, adequação e garantia dos exames.', 'A instalação deve ser necessariamente em prédio autônomo? Não. O artigo admite unidade autônoma OU anexo a estabelecimento penal.', 'Ser anexo autoriza dispensar exames ou estrutura necessária? Não. A forma de instalação não suprime a função do Centro nem suas exigências pertinentes.')
add(98,'Sem Centro de Observação, Comissão Técnica realiza exames. Resposta: substituição supletiva prevista.', 'Não é autorização para qualquer servidor sem qualificação elaborar todos os laudos.', 'A inexistência do Centro torna todo exame impossível por lei? Não. A Comissão Técnica pode realizar os exames na falta dele.', 'A regra transfere a decisão judicial de progressão à Comissão? Não. Suprir realização de exames não equivale a conceder benefício judicial.')
add(99,'Pessoa submetida à medida recebe avaliação individualizada de saúde. Resposta: texto do HCTP precisa ser integrado ao modelo de cuidado da Lei 10.216.', 'Diagnóstico não implica automaticamente internação asilar ou institucionalização perpétua.', 'Qualquer diagnóstico obriga internação sem examinar alternativas? Não. Lei 10.216 exige insuficiência dos recursos extra-hospitalares e cuidado adequado; não basta etiqueta diagnóstica.', 'O artigo manda manter pessoa para sempre no hospital? Não. Destinação textual não elimina direitos, limites da medida ou avaliação de cuidado.',notes=['Integre Lei 10.216/2001 e políticas antimanicomiais atuais; não certificar implantação local ou toda regulamentação CNJ. Fonte do ato CNJ não obtida nesta coleta.','Não confundir inimputabilidade com diagnóstico isolado; CP 26 tem requisitos próprios.'],sources=[HEALTH,CP])
add(100,'Internado recebe exame psiquiátrico e demais avaliações necessárias. Resposta: obrigatoriedade de cuidado, não permissão de qualquer procedimento invasivo.', 'Pesquisa científica exige consentimentos e controles próprios da Lei 10.216, art. 11.', 'A obrigatoriedade do exame autoriza experimento compulsório irrestrito? Não. Exame necessário ao tratamento e pesquisa têm regimes e garantias distintos.', 'O artigo permite excluir parte dos internados de todo exame necessário? Não. O texto refere TODOS os internados, integrado a necessidades clínicas e direitos.',sources=[HEALTH])
add(101,'Tratamento ambulatorial ocorre em serviço adequado fora do HCTP. Resposta: alternativa textual possível, integrada ao cuidado comunitário.', 'Ambulatorial não significa internação obrigatória só porque o artigo menciona hospital.', 'Somente dentro do HCTP pode ocorrer tratamento ambulatorial? Não. O artigo admite outro local com dependência médica adequada, integrado ao modelo de saúde atual.', 'Ambulatorial e internação são modalidades idênticas? Não. A modalidade precisa ser distinguida e justificada segundo necessidades clínicas e regras aplicáveis.',sources=[HEALTH])
add(102,'Pessoa presa provisoriamente é recolhida conforme destinação da cadeia pública. Resposta: destinação legal, sem prejuízo da validade do título de custódia.', 'Ter ocorrido flagrante não autoriza manter prisão indefinidamente sem controle judicial.', 'A destinação da cadeia pública torna legal qualquer prisão nela realizada? Não. Local adequado e título válido de custódia são requisitos distintos.', 'O artigo destina a cadeia a condenados definitivos do regime fechado? Não. Seu destinatário textual é o preso PROVISÓRIO, não substituição automática de penitenciária.',simples='A cadeia pública destina-se ao recolhimento de presos provisórios. Essa destinação não valida a prisão por si nem dispensa título e controles judiciais; não confundir provisório com toda pessoa que simplesmente aguarda qualquer recurso.')
add(103,'Comarca tem cadeia pública próxima ao meio social/familiar. Resposta: artigo prevê ao menos uma por comarca.', 'Norma não comprova que toda comarca tem unidade instalada nem garante escolher livremente qualquer prisão.', 'O mínimo textual é uma por Estado? Não. É pelo menos uma por COMARCA, com finalidade social/familiar e de administração da Justiça.', 'A previsão comprova existência concreta em toda comarca? Não. Obrigação normativa e implantação factual são coisas diferentes; consultar situação local.')
add(104,'Projeto de cadeia pública prevê proximidade urbana e requisitos mínimos do art. 88. Resposta: distância e salubridade devem ser integradas.', 'Não copiar isolamento distante de penitenciária masculina para toda cadeia pública.', 'O artigo determina instalar cadeia pública sempre longe da cidade? Não. Prevê proximidade de centro urbano, com exigências mínimas do art. 88.', 'A proximidade elimina requisitos de área e salubridade? Não. O artigo exige ambos; não usar um requisito para dispensar os demais.')
add(105,'Sentença definitiva de prisão recebe guia após trânsito e prisão no recorte legal. Resposta: guia definitiva tem marco próprio.', 'Execução provisória para benefícios de preso cautelar e situações constitucionais específicas exigem exame próprio, não autorização geral de prisão antes do trânsito.', 'A guia definitiva do artigo dispensa trânsito em julgado? Não. A hipótese textual começa pelo trânsito, sem confundir guia provisória com antecipação geral da pena.', 'O trânsito torna obrigatória prisão imediata de toda pessoa sem examinar sentença/regime? Não. O texto também distingue réu preso ou que vier a ser preso e título aplicável.',notes=['Não certificar universalmente todos os casos de execução provisória/Júri apenas por este artigo; examinar disciplina e jurisprudência específicas.'])
add(106,'Remição muda a data de término; a guia recebe retificação. Resposta: manter dados judiciais e ciência ao MP.', 'Nova guia não pode manter data antiga só porque a sentença não mudou.', 'Alteração da duração da pena permite deixar a guia desatualizada? Não. §2º exige retificação quando houver mudança no início ou duração da execução.', 'A menção de funcionário vale para todo servidor público indiscriminadamente? Não. §3º refere Administração da JUSTIÇA CRIMINAL ao tempo do fato, integrada ao art. 84.')
add(107,'Unidade recebe guia judicial para cumprimento de pena e dá ciência ao condenado. Resposta: execução tem registro e atualizações.', 'Prisão cautelar tem título próprio; não transformar sem guia de pena em autorização de fuga ou nulidade automática de qualquer custódia.', 'Ninguém recolhido sem guia significa inexistência de todo flagrante? Não. O recorte é cumprimento de pena privativa, distinto de prisão cautelar legalmente fundada.', 'Cálculo de remição pode ser ignorado no prontuário? Não. §2º prevê aditamento das remições e retificações durante a execução.',atencao=['O recorte PARA CUMPRIMENTO DE PENA impede slogan sobre toda prisão.','Não tratar referência a livro como vedação universal de sistemas eletrônicos oficiais.'])
add(108,'Condenado apresenta transtorno mental superveniente e recebe avaliação adequada. Resposta: cuidado exige integração clínica/jurídica, não internação asilar automática.', 'A doença não prova sozinha inimputabilidade ao tempo do crime nem converte definitivamente a pena sem decisão.', 'Qualquer diagnóstico superveniente muda automaticamente a sentença para absolvição? Não. É situação da execução, distinta da capacidade ao tempo do fato e de conversão judicial do 183.', 'O texto permite abandonar tratamento ou internar sem necessidade clínica? Não. Integrar Lei 10.216, direitos e insuficiência dos recursos extra-hospitalares para internação.',sources=[HEALTH],notes=['Não certificada toda regulamentação antimanicomial ou implantação local; sem treino de internação automática por diagnóstico.'])
add(109,'Pena termina e não existe outro título de prisão; juiz expede alvará. Resposta: libertação no recorte, com conferência de outras ordens.', 'Outra custódia válida não pode ser ignorada; inexistência de outro título não permite prolongar pena já extinta.', 'Extinção desta pena elimina qualquer outra prisão válida? Não. O artigo ressalva SE POR OUTRO MOTIVO NÃO ESTIVER PRESO; examinar outros títulos.', 'O diretor escolhe prolongar a pena por conveniência? Não. Cumprida/extinta, cabe providência judicial de liberdade quando não houver outra causa legal de prisão.')
add(110,'Sentença fixa regime conforme CP 33 e critérios pertinentes. Resposta: competência judicial e individualização.', 'Não presumir fechado apenas pela gravidade abstrata ou por todo crime hediondo, sem regime constitucional aplicável.', 'Quem escolhe o regime inicial é necessariamente o diretor? Não. O juiz o estabelece na sentença, observado CP 33 e critérios pertinentes.', 'Regime inicial e progressão posterior são a mesma decisão? Não. A sentença fixa início; execução examina progressão e eventuais modificações.',sources=[CP])
add(111,'Restam quatro anos e sobrevém pena de dois: analisar soma de seis para regime, com deduções cabíveis. Resposta: soma do RESTANTE, não repetir pena inteira cumprida.', 'Unificar penas não prova por si falta grave ou reinício automático de todos os prazos de benefícios.', 'Condenação superveniente soma-se sempre à pena original inteira? Não. O parágrafo manda somar ao RESTANTE da pena em cumprimento, com cálculos pertinentes.', 'A soma permite ignorar remição/detração quando aplicáveis? Não. O caput exige observar essas deduções na determinação do regime.')
add(112,'Texto compilado atual fixa setenta por cento para hediondo primário. Resposta: é regra textual de 2026; aplicar a caso exige data do fato, lei cabível e requisitos.', 'Para fato antigo, não impor percentual agravado de 2026 automaticamente; comparar regimes íntegros e garantias intertemporais.', 'Todo hediondo primário antigo passou automaticamente de quarenta para setenta por cento? Não. Lei penal mais gravosa não retroage; texto atual e regime aplicável ao fato são distintos.', 'Cumprir a fração torna automática a progressão sem outros requisitos? Não. Há boa conduta, exame no regime aplicável, manifestação de MP/defesa e decisão motivada, além das vedações pertinentes.',simples='Progressão exige análise judicial do requisito temporal e subjetivo. Compilado atual: caput de 1/6; incisos I–III alterados pela Lei 15.402/2026, ressalvando Título XII do CP nos I/II; incisos V–VIII da Lei 15.358/2026 trazem 70%, 75%, 80% e 85% conforme hipóteses. Não aplicar tudo retroativamente nem resolver por slogan o inciso IV residual. §1º inclui resultados de exame criminológico na redação de 2024; sua incidência temporal exige jurisprudência pertinente. Progressão especial de 1/8 do §3º tem requisitos CUMULATIVOS. Tráfico privilegiado não é hediondo para este artigo. Falta grave interrompe progressão com base na pena remanescente; §7º admite recuperação de bom comportamento antes de um ano na hipótese expressa.',pontos=['Separar texto vigente e regime temporal do fato; nova fração mais gravosa não vale automaticamente para condenações antigas.','Lei 15.402 publicada/vigente em 8/5/2026; Lei 15.358 alterou hediondos em 2026.','Incisos I/II ressalvam Título XII do CP; inciso IV conserva redação anterior, sem exercício que resolva toda sobreposição por automatismo.','§1º: boa conduta e exame; §2º decisão motivada com MP e defensor.','§3º: 1/8, primária, boa conduta, sem violência, crime contra filho/dependente ou integração de organização, cumulativamente.','§6º: interrupção para progressão, base remanescente; não reinício universal de todo benefício.'],atencao=['STF Tema 1408/RE 1536743: notícia de 7/7/2025 reconhece repercussão geral; não é tese de mérito certificada. Não certificada decisão posterior integral nesta revisão.','Controle da Antifacção em ADIs não declarado resolvido. Não apresentar percentuais atuais como solução judicial de todas as hipóteses.','Bom comportamento após um ano OU antes na condição do §7º; não fixar um ano invariável.','Súmulas 534/535: falta grave interrompe progressão, não prazo de indulto/comutação; cada benefício tem requisitos próprios.'],sources=[L402,L358,L843,STFEX,SUM(534),SUM(535)])
add(113,'Condenado aceita programa e condições válidas do aberto. Resposta: aceitação é requisito do ingresso.', 'Aceitar não convalida condição ilegal ou elimina o direito de impugnar decisão.', 'A aceitação transforma qualquer exigência ilegal em válida? Não. O programa precisa observar lei e garantias; consentimento não substitui legalidade.', 'O ingresso no aberto dispensa conhecer e aceitar condições? Não. O artigo supõe aceitação do programa e das condições judiciais pertinentes.')
add(115,'Juiz fixa monitoramento motivado no aberto além das quatro condições gerais. Resposta: especial e geral têm regimes distintos.', 'Não converter pena restritiva de direitos em condição especial extra indevida do aberto; Súmula 493.', 'Pode impor prestação de serviços como pena substitutiva só por condição especial do aberto? Não. Súmula 493/STJ considera inadmissível pena substitutiva do CP 44 como condição especial.', 'Comparecimento ao juízo é necessariamente diário? Não. Inciso IV prevê quando determinado; não inventar frequência uniforme para todos.',sources=[L843,SUM(493)],notes=['Monitoramento é hipótese possível, não obrigatório indistintamente por este artigo; há regras especiais em outras normas.'])
add(116,'Novo horário de trabalho justifica revisão motivada das condições. Resposta: condenado também pode requerer ajuste.', 'Mudança pessoal sem decisão não equivale à alteração judicial autorizada.', 'Somente o Ministério Público pode pedir alteração? Não. O artigo inclui autoridade administrativa e condenado, além da iniciativa judicial no seu recorte.', 'O condenado pode simplesmente trocar condição válida por outra? Não. É decisão do juiz conforme circunstâncias, não alteração unilateral por preferência.')
add(117,'Condenado de setenta e dois anos no aberto pede recolhimento residencial. Resposta: está no recorte etário, com exame judicial do caso.', 'Domiciliar cautelar do CPP e soluções excepcionais de execução não são idênticas ao rol textual do 117.', 'A idade textual é maior de sessenta anos? Não. O inciso I diz MAIOR DE SETENTA, distinto de outros marcos legais da pessoa idosa.', 'O rol permite negar indistintamente toda solução excepcional fora do aberto? Não. Examinar fundamentos e jurisprudência próprios; o recorte textual não certifica todas as exceções constitucionais.',notes=['Não confundir ausência de vaga, cuidado médico e domiciliar cautelar; nenhuma concessão universal automática.'])
add(118,'Falta grave apurada leva a exame de regressão definitiva, com oitiva no recorte legal. Resposta: decisão fundamentada e defesa.', 'Regressão cautelar e definitiva têm pressupostos/etapas distintos; não concluir pela literalidade que toda providência urgente é impossível.', 'A regressão é sempre somente um degrau? Não. O caput admite qualquer regime mais rigoroso nas hipóteses legais; decisão precisa de fundamento.', 'A falta de recursos para pagar multa autoriza prisão por dívida? Não. O texto fala podendo; integrar regime atual da multa e garantias, sem regressão automática por pobreza.',notes=['Diferenciar tutela cautelar e regressão definitiva; não certificada integralmente jurisprudência de toda hipótese.','Não ensinar antiga multa como conversão automática em prisão.'])
add(119,'Lei local disciplina aspectos complementares do aberto. Resposta: competência complementar, sem contrariar normas federais/Constituição.', 'Complementar não permite criar nova pena criminal por norma administrativa.', 'Qualquer norma local pode afastar a LEP por ser complementar? Não. Complementação é subordinada ao quadro legal e constitucional pertinente.', 'O artigo veda toda disciplina local do regime aberto? Não. Autoriza normas complementares, sem atribuir competência ilimitada para criar sanções.')
add('119-a','Condenado por crime contra dignidade sexual tem pedido de regime benéfico examinado à luz do exame e do regime temporal. Resposta: art. 119-A é alteração de 2025.', 'Laudo não é garantia científica absoluta de que nunca haverá crime nem substitui os demais requisitos.', 'A previsão do exame permite retroagir toda exigência mais gravosa sem análise? Não. Lei 15.280/2025 precisa de integração temporal e constitucional; não requisito original de 1984.', 'Resultado com indícios de não repetição equivale a certeza absoluta sobre o futuro? Não. O texto fala INDÍCIOS, com avaliação técnica e decisão, não previsão infalível.',sources=['https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/lei/l15280.htm'],notes=['Não certificada toda jurisprudência/controle posterior desse artigo; sem exercício de aplicação automática a crimes anteriores.'])
add(120,'Preso provisório precisa de tratamento médico externo e recebe permissão com escolta. Resposta: diretor concede no recorte textual.', 'Saída temporária sem vigilância direta é modalidade diferente; restrição de uma não revoga automaticamente toda permissão médica.', 'A permissão só existe para condenado no semiaberto? Não. Inclui fechado, semiaberto e provisório, com escolta e fatos enumerados.', 'A doença de qualquer conhecido está automaticamente no inciso I? Não. O rol indica familiares específicos; necessidade médica própria tem inciso II.')
add(121,'Permissão para tratamento dura o necessário ao atendimento. Resposta: duração vinculada à finalidade, não prazo antigo da saidinha.', 'Sete dias do art. 124 revogado não é prazo geral de toda permissão de saída.', 'O artigo fixa sete dias universais para tratamento? Não. Prevê duração necessária à finalidade da saída, integrada à autorização pertinente.', 'Encerrada a finalidade, a permissão autoriza permanecer fora por conveniência? Não. O tempo é limitado à finalidade e às condições da autorização.')
add(122,'Semiaberto pede saída para curso no recorte atual e preenche condições. Resposta: examinar estudo, regime temporal e vedações.', 'Visita familiar dos incisos revogados não é hipótese atual universal; para fato antigo, verificar irretroatividade e decisão pertinente.', 'A revogação das visitas permite aplicar regra mais gravosa indistintamente a fato de 2020? Não. HC 240770/STF restabeleceu benefícios no caso antigo; distinguir decisão individual de tese universal.', 'A saída atual para estudo é necessariamente sem nenhum monitoramento? Não. Sem vigilância direta não impede equipamento eletrônico determinado pelo juiz.',notes=['Lei 14.843: publicação inicial em 11/4/2024 e promulgação de partes vetadas têm marcos diferentes; a íntegra da promulgação não foi recuperada nesta consulta. Não atribuir toda revogação ao mesmo dia.','§2º veda saída/trabalho externo sem vigilância direta para hediondo ou violência/grave ameaça no regime aplicável.','§3º: duração necessária às atividades discentes; art. 124 revogado não ensina sete dias/cinco saídas como regra atual.','STF Tema 1381 consta na notícia sobre exame; não certificada tese posterior de mérito.'],sources=[L843,STFEXIT])
add(125,'Baixo aproveitamento do curso ou falta grave devidamente apurada exige tratar revogação do benefício. Resposta: consequências legais com controle e garantias.', 'Denúncia informal de falta não dispensa apuração, nem a palavra automaticamente entrega competência irrestrita à direção.', 'A palavra automaticamente dispensa toda defesa e controle judicial? Não. Não substitui apuração válida dos fatos, garantias e atuação competente.', 'A recuperação depende exclusivamente de nova lei de indulto? Não. O parágrafo indica absolvição, cancelamento da punição OU demonstração de merecimento.',atencao=['Corrigido exercício antigo que negava indistintamente necessidade de controle judicial.','Integrar regime atual do 122; benefício revogado não restaura incisos antigos para todos.'])
add(126,'Aluno estuda doze horas distribuídas em três dias. Resposta: um dia remido; trinta dias válidos de trabalho geram dez.', 'Doze horas concentradas num único dia não satisfazem por si a distribuição mínima para estudo.', 'O estudo tem apenas quantidade total de horas, sem distribuição? Não. São doze horas divididas em NO MÍNIMO TRÊS DIAS, com comprovação e requisitos.', 'Prisão domiciliar exclui automaticamente toda remição? Não. §9º da Lei 15.402/2026 afasta impedimento pelo regime, sem dispensar atividade válida e prova.',notes=['Conclusão de fundamental/médio/superior durante pena, certificada: acréscimo de um terço do tempo remido de estudo, não de toda pena.','Súmula 562 admite trabalho extramuros no fechado/semiaberto; não exigir trabalho apenas dentro da prisão.','Aberto/livramento têm recorte de estudo do §6º; não universalizar trabalho para todo regime pelo caput.','Acidente impeditivo tem §4º; não equiparar qualquer inatividade a remição automática.'],sources=[L402,SUM(562)])
add(127,'Há trinta dias remidos e falta grave apurada. Resposta: juiz pode revogar ATÉ dez, com individualização, não necessariamente dez.', 'Não retirar todos os trinta com regra anterior à Lei 12.433/2011.', 'A perda máxima de um terço é sempre perda obrigatória integral dessa fração? Não. O verbo poderá e limite ATÉ exigem decisão e individualização conforme art. 57.', 'A direção pode cancelar sozinha todo tempo remido? Não. A norma atribui decisão ao juiz e limita a perda, com regime de apuração/defesa.')
add(128,'Dez dias declarados remidos entram como pena cumprida no cálculo pertinente. Resposta: não simples redução de benefício isolado.', 'Contar os mesmos dez duas vezes em rubricas idênticas não é autorizado por para todos os efeitos.', 'Tempo remido só vale para saída temporária? Não. O artigo o computa como pena cumprida PARA TODOS OS EFEITOS, nos cálculos cabíveis.', 'A expressão autoriza duplicar o mesmo crédito no cálculo? Não. Efeito amplo não é contagem em dobro sem fundamento legal.')
add(129,'Direção manda registro mensal e estudante externo comprova frequência/aproveitamento mensalmente. Resposta: obrigações diferentes e cumuláveis.', 'Enviar relatório anual não atende periodicidade mensal apenas porque ano reúne todos os meses.', 'A comprovação escolar externa pode ser só verbal sem declaração prevista? Não. §1º exige declaração da unidade de ensino com frequência e aproveitamento.', 'O condenado pode ser privado de toda relação de dias remidos? Não. §2º manda fornecer a relação, permitindo conhecimento e conferência do cálculo.')
add(130,'Responsável atesta conscientemente serviço não prestado para obter remição. Resposta: remissão à falsidade ideológica do CP 299.', 'Erro corrigível sem elementos subjetivos não deve ser tratado automaticamente como crime consumado.', 'Toda divergência de planilha prova por si falsidade ideológica? Não. Apurar conteúdo, finalidade, autoria e elementos do CP 299, não presumir crime de qualquer erro.', 'O artigo prevê apenas advertência disciplinar sem remissão penal? Não. Define remissão ao crime do CP 299, com análise dos requisitos pertinentes.',sources=[CP])
add(131,'Juiz examina livramento com requisitos CP 83 e manifestações pertinentes. Resposta: Conselho não concede sozinho o benefício.', 'Frações da progressão não são automaticamente frações do livramento.', 'Pode substituir todos os requisitos do CP 83 por bom comportamento isolado? Não. Há requisito de pena, frações, reparação e demais condições/vedações pertinentes.', 'A remissão ao Conselho elimina manifestação da defesa prevista no 112, §2º? Não. Integrar ambos os dispositivos e garantias; não leitura isolada para suprimir defensor.',sources=[CP],notes=['Aplicar vedações atuais e regime temporal; não garantir livramento para todas as modalidades de hediondo.'])
add(132,'Liberado apto ao trabalho deve buscar ocupação lícita em prazo razoável e informar ao juízo. Resposta: aptidão e prazo são requisitos expressos.', 'Mudar de residência exige comunicação no recorte facultativo; mudar de comarca exige prévia autorização na condição geral.', 'Obter ocupação ignora incapacidade de trabalho? Não. §1º,a, condiciona a ser APTO e concede prazo razoável; não impor emprego imediato impossível.', 'Toda mudança de endereço exige a mesma autorização da mudança de comarca? Não. §2º,a, fala comunicação; §1º,c, autorização prévia para território da comarca.',sources=[L843])
add(133,'Mudança de comarca é autorizada; cópia da sentença segue ao novo juízo e autoridade de observação. Resposta: dois destinatários.', 'Mudança física não constitui autorização judicial tácita nem dispensa a comunicação institucional.', 'A cópia vai apenas ao novo empregador? Não. O artigo indica juízo do lugar e autoridade de observação/proteção, no contexto autorizado.', 'A remessa substitui pedido de autorização para mudar? Não. Ela decorre de mudança permitida, não legaliza unilateralmente transferência indevida.')
add(134,'Liberado é advertido a apresentar-se imediatamente no novo local autorizado. Resposta: apresentação pessoal/institucional pertinente.', 'Não inventar trinta dias livres para se apresentar só porque outra norma tem esse prazo.', 'O artigo prevê prazo universal de trinta dias? Não. Determina apresentação IMEDIATA às autoridades do artigo anterior, sem esse prazo inventado.', 'Enviar cópia pelo juízo elimina todo dever do liberado de apresentar-se? Não. Comunicação institucional e apresentação advertida são obrigações distintas.')
add(135,'Tribunal reforma negativa de livramento; autos retornam à execução para providências. Resposta: reforma não elimina implementação do benefício.', 'Não concluir que o diretor pode inventar condições contrárias à decisão do tribunal.', 'Toda providência executória fica obrigatoriamente no tribunal que reformou? Não. O artigo manda baixar os autos ao juízo da execução para providências cabíveis.', 'O retorno permite ignorar a reforma por simples preferência administrativa? Não. É implementação do decidido, com medidas e controles pertinentes.')
add(136,'Benefício concedido; carta com sentença integral segue em duas vias para administração e Conselho. Resposta: destinatários próprios.', 'Não confundir carta de livramento e guia definitiva de recolhimento.', 'Uma única via ao MP substitui os dois destinatários textuais? Não. O artigo indica duas vias, para autoridade administrativa executora e Conselho Penitenciário.', 'A carta decide por si conceder benefício que o juiz negou? Não. É documento decorrente da concessão, distinto da decisão de mérito.')
add(137,'Na cerimônia, liberando declara aceitação e termo é remetido ao juízo. Resposta: registro da ciência/aceitação.', 'Quem não pode escrever pode ter assinatura a rogo; incapacidade de escrita não extingue acesso ao benefício.', 'Não saber escrever torna impossível lavrar termo válido? Não. §1º admite alguém a rogo, com formalidades pertinentes, sem excluir o beneficiário.', 'O termo deve ficar exclusivamente na administração sem cópia judicial? Não. §2º determina remessa de cópia ao juízo da execução.')
add(138,'Liberado recebe pecúlio, pertences e documento das condições. Resposta: caderneta ou salvo-conduto na falta.', 'A falta material de caderneta não autoriza liberar sem registrar condições e identificação.', 'Sem caderneta, o artigo elimina todo documento substitutivo? Não. §2º prevê salvo-conduto com condições e alternativas de identificação.', 'O documento apenas identifica, sem espaço para cumprimento de condições? Não. §§1º/3º incluem condições e espaço de consignação do cumprimento.')
add(139,'Patronato acompanha condições e ajuda a conseguir atividade lícita. Resposta: fiscalização E proteção.', 'Proteção não autoriza entidade conceder ou revogar livramento por conta própria.', 'A única finalidade é vigiar sem oferecer orientação? Não. Inciso II prevê proteção, orientação e auxílio na atividade laborativa.', 'Relatório da entidade vale como decisão judicial de revogação? Não. Subsidia representação do Conselho e procedimento competente, não sentença substitutiva.')
add(140,'Hipótese de revogação facultativa é examinada; juiz mantém benefício e adverte ou agrava condições. Resposta: opção legal com consequência.', 'Condenação definitiva a prisão por crime no benefício tem regime obrigatório do CP 86, não mera opção irrestrita.', 'Todo motivo torna revogação facultativa? Não. CP 86/87 distinguem hipóteses obrigatórias e facultativas, com pressupostos próprios.', 'Manter benefício na facultativa permite ignorar advertência/agravamento do parágrafo? Não. O texto determina advertir OU agravar, não ausência de providência por automatismo.',sources=[CP])
add(141,'Revogação decorre de infração ANTERIOR ao livramento. Resposta: período de prova computado e possível soma para novo benefício.', 'Crime DURANTE o benefício tem tratamento distinto; não aplicar exceção de anterioridade apenas porque julgamento foi posterior.', 'A data decisiva é só a sentença nova, sem considerar quando ocorreu o fato? Não. O artigo diferencia infração anterior à vigência do livramento; cronologia do fato importa.', 'O período de prova é necessariamente desprezado nesta hipótese anterior? Não. O texto manda computar e permite soma das duas penas para análise de novo livramento.')
add(142,'Livramento é validamente revogado por motivo diferente da infração anterior. Resposta: art. 142 não conta tempo solto e impede novo benefício na mesma pena.', 'Descumprimento alegado não equivale automaticamente a revogação válida, nem falta de suspensão tempestiva supera Súmula 617.', 'O artigo autoriza ignorar a exceção de crime anterior do 141? Não. Ele trata de OUTRO MOTIVO; a hipótese anterior tem efeito próprio.', 'O impedimento refere-se a toda pena futura de qualquer processo? Não. A expressão é EM RELAÇÃO À MESMA PENA, sem proibição vitalícia universal.',notes=['Integrar procedimento de revogação e Súmula 617; não retirar tempo por mera notícia de descumprimento.'],sources=[SUM(617)])
add(143,'Juiz examina requerimento de revogação e ouve liberado. Resposta: decisão judicial, não mero ato do Conselho.', 'Representação e requerimento não autorizam entidade revogar por conta própria.', 'O Conselho revoga diretamente por apresentar representação? Não. A representação provoca o procedimento; a revogação é decretada pelo juiz, ouvido o liberado.', 'O artigo dispensa oitiva em toda revogação definitiva? Não. Exige ouvir o liberado, com garantias e integração ao procedimento pertinente.')
add(144,'Defensoria requer ajustar condição; liberado é ouvido e decisão lida/registrada. Resposta: legitimidade e ciência.', 'Mudar condição judicial não é alteração unilateral pelo órgão que acompanha.', 'A Defensoria foi excluída dos legitimados? Não. Redação da Lei 12.313/2010 a inclui expressamente entre requerentes.', 'A decisão pode ser comunicada sem os procedimentos referidos por simples conveniência? Não. O artigo remete à leitura e formalidades do 137 no recorte legal.')
add(145,'Nova infração no período leva a exame judicial de suspensão, com órgãos ouvidos. Resposta: suspensão não é revogação final automática.', 'Se não houve suspensão/revogação antes do término, integrar Súmula 617; não revogar depois só pela notícia de crime antigo.', 'O tipo de providência é revogação final obrigatória desde a primeira notícia? Não. O artigo prevê suspensão e possível prisão nos pressupostos legais; revogação depende da decisão final.', 'Uma providência posterior ao fim sempre desfaz benefício já concluído? Não. Súmula 617 exige considerar ausência de suspensão/revogação anterior ao fim do período de prova.',sources=[SUM(617)],notes=['Prisão exige fundamento, não automatismo pela notícia de infração.'])
add(146,'Período termina sem suspensão/revogação tempestiva; examina-se extinção conforme Súmula 617. Resposta: não prorrogar indefinidamente por mera demora administrativa.', 'Se houve suspensão tempestiva válida, não concluir extinção só porque calendário originalmente previsto chegou ao fim.', 'Só olhar se houve revogação basta ignorando suspensão válida? Não. Súmula 617 diferencia ausência de suspensão OU revogação anterior ao término; examinar situação concreta.', 'A extinção depende sempre de novo pedido pessoal? Não. O artigo admite iniciativa judicial e dos legitimados; não imposição universal de requerimento do interessado.',sources=[SUM(617)],notes=['Integre CP 89/90 e procedimento; não extinção automática em qualquer processo sem conferir suspensão tempestiva.'])
add(147,'Após trânsito da restritiva, juiz requisita colaboração pública e solicita a particular. Resposta: verbos e destinatários distintos.', 'Não chamar particular a prestar qualquer atividade obrigatoriamente por simples requisição deste artigo.', 'A execução da restritiva aqui dispensa trânsito? Não. O caput começa por sentença TRANSITADA EM JULGADO, com atuação do juízo de execução.', 'A colaboração de particular é descrita como requisição obrigatória igual à pública? Não. O texto distingue REQUISITAR públicas e SOLICITAR particulares.')
add(148,'Mudança de jornada justifica ajustar horário de serviço comunitário motivadamente. Resposta: forma de cumprimento, não troca livre de pena.', 'Ajustar horários não significa transformar qualquer modalidade de restritiva em outra por conveniência.', 'O juiz pode alterar forma apenas no primeiro dia? Não. O texto admite em QUALQUER FASE, com motivação e adequação pertinentes.', 'A regra permite substituir livremente toda espécie de pena restritiva? Não. Trata da FORMA de prestação de serviços e limitação de fim de semana, com os recortes legais.')
add(149,'Juiz organiza tarefas compatíveis com emprego e aptidões. Resposta: considerar CP 46, §3º, uma hora por dia de condenação, não fórmula universal isolada de oito horas.', 'O texto residual de oito horas semanais da LEP não resolve sozinho duração/calendário de todas as condenações atuais.', 'Todo caso atual exige invariavelmente oito horas por semana pela frase antiga? Não. Integrar CP 46, §3º/§4º, vigente: uma hora por dia de condenação e possibilidades legais de cumprimento, sem prejudicar jornada.', 'A execução tem início só da sentença, sem primeiro comparecimento? Não. §2º do artigo fixa primeiro comparecimento no recorte, distinto do trânsito necessário à execução.',simples='Juiz designa entidade credenciada/convencionada, intima para dias/horários e ajusta a forma à jornada. O §1º conserva oito horas semanais no texto; integrar ao CP 46, §§3º/4º, atual, que calcula uma hora de tarefa por dia de condenação e admite condições próprias de cumprimento. Não apresentar oito horas como fórmula invariável de todo caso. §2º: início no primeiro comparecimento.',atencao=['CP 46 foi alterado pela Lei 9.714/1998; distinguir duração total da pena, quantidade de horas e calendário semanal.','Não prejudicar jornada normal; trabalho é gratuito e conforme aptidões, sem prometer livre escolha de entidade pelo condenado.'],sources=[CP])
